import{z as l,x as d,o as r,c as o,q as s,j as i,D as e,d as t,s as A,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"自适应查询处理","description":"","frontmatter":{"title":"自适应查询处理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/adaptive-query-processing.md","filePath":"cs/adaptive-query-processing.md","lastUpdated":1791063341000}'),p={name:"cs/adaptive-query-processing.md"};function D(C,a,m,u,h,P){const n=d("Mermaid");return r(),o("div",null,[a[2]||(a[2]=s('<h1 id="自适应查询处理" tabindex="-1">自适应查询处理 <a class="header-anchor" href="#自适应查询处理" aria-label="Permalink to &quot;自适应查询处理&quot;">​</a></h1><div class="epigraph"><p>计划在优化时冻结；数据在执行时揭晓。自适应处理在管道中观察基数与延迟，切换算子或重优化剩余树。</p><footer>—— 据 Kabra and DeWitt；Avnur and Hellerstein, Eddies；Deshpande, Ives and Raman 综述</footer></div><p><a href="/cs/cost-model-calibration">上一课</a>把尺子对准机器。本课不重拟合权重。缺口是运行时：即使基数与权重当时看起来对，参数、倾斜、相关仍可能让中间结果爆。自适应查询处理（AQP）在执行中收集反馈，改变剩余计划，而不是等语句结束才把实际行数写进日志。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态优化：一次 DP，整树固定。发现哈希表打满内存时已经晚了。策略包括：缓冲监测点，若实际行数与估计偏离超过阈值则<strong>重优化</strong>未执行子树；选择路由（eddy）把元组动态送给当时最合适的算子；切换连接算法（hybrid hash 的 infight 调整）。缺口是<strong>正确性</strong>：切换后指称仍是同一查询，隔离与谓词不能丢。</p><p>与计划缓存冲突：自适应改的是这一次执行，下次仍可能用坏的缓存计划——反馈应能更新统计或令牌化「这次参数要特殊计划」。</p><p><span class="marginnote">Kabra and DeWitt 的 mid-query reoptimization。Avnur and Hellerstein 的 Eddy（SIGMOD 2000）。综述见 IEEE TKDE 上 Deshpande, Ives, Raman。本课不把连续自适应当默认 OLTP 路径：短查询重优化成本可能高于执行。</span></p><p><span class="marginnote">直觉类比：静态计划像出发前定死路线的导航，AQP 是边开边看路况——发现前方拥堵（基数爆炸）就原地重规划剩下的路；已经开过的路（物化的中间结果）不必重走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入测量算子或在现有迭代器里计数。阈值：估计/实际比超限 → 停管道、把已有中间结果物化、对剩余 SQL（或逻辑树）再跑 DP。Eddies：元组带就绪标志，路由策略学习哪一谓词选择率高。本课以重优化为主，eddy 点名。</p><p>内存：自适应切到 Grace 分区哈希（后课执行引擎）是算子内自适应，不一定重跑整个优化器。</p>',11)),(r(),i(B,null,{default:e(()=>[A(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%9D%99%E6%80%81%E8%AE%A1%E5%88%92%22%5D%20--%3E%20RUN%5B%22%E6%89%A7%E8%A1%8C%E5%B9%B6%E8%AE%A1%E6%95%B0%22%5D%0A%20%20RUN%20--%3E%20OK%5B%22%E8%AF%AF%E5%B7%AE%E5%8F%AF%E6%8E%A5%E5%8F%97%22%5D%0A%20%20RUN%20--%3E%20RE%5B%22%E7%89%A9%E5%8C%96%E4%B8%AD%E9%97%B4%E7%BB%93%E6%9E%9C%22%5D%0A%20%20RE%20--%3E%20DP2%5B%22%E9%87%8D%E4%BC%98%E5%8C%96%E5%89%A9%E4%BD%99%E6%A0%91%22%5D%0A%20%20DP2%20--%3E%20RUN2%5B%22%E7%BB%A7%E7%BB%AD%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"事务：重优化发生在同一语句、同一快照；不能换成另一隔离语义。并行：exchange 已把数据切到线程，重优化要协调暂停。OLTP 短查询：自适应常关闭，只在 OLAP 长查询开。",-1)),a[5]||(a[5]=E("p",null,"反馈回路：把实际基数写回，供下一次优化或学习型优化器。本课只要求这一次执行能救，学习模型下一课。",-1)),a[6]||(a[6]=E("p",null,"第一张图画的是监测—重优化的控制回路；这张图回答第二个问题：一个具体的翻车现场——优化器估 1 万行、实际滚来 500 万行，执行中途到底发生了什么。",-1)),(r(),i(B,null,{default:e(()=>[A(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20EST%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E4%BC%B0%E8%AE%A1%EF%BC%9A1%20%E4%B8%87%E8%A1%8C%22%5D%20--%3E%20START%5B%22%E6%8C%89%E5%86%85%E5%AD%98%E5%93%88%E5%B8%8C%E8%BF%9E%E6%8E%A5%E5%BC%80%E8%B7%91%22%5D%0A%20%20START%20--%3E%20MON%7B%22%E7%9B%91%E6%B5%8B%E7%82%B9%EF%BC%9A%E5%AE%9E%E9%99%85%E8%A1%8C%E6%95%B0%EF%BC%9F%22%7D%0A%20%20MON%20--%3E%7C%22500%20%E4%B8%87%E8%A1%8C%EF%BC%8C%E8%B6%85%E9%98%88%E5%80%BC%E6%95%B0%E7%99%BE%E5%80%8D%22%7C%20SPILL%5B%22%E5%93%88%E5%B8%8C%E8%A1%A8%E6%89%93%E6%BB%A1%E5%86%85%E5%AD%98%EF%BC%8C%E5%90%91%E5%A4%96%E6%BA%A2%E5%86%99%22%5D%0A%20%20SPILL%20--%3E%20MATER%5B%22%E6%9A%82%E5%81%9C%EF%BC%8C%E7%89%A9%E5%8C%96%E5%B7%B2%E7%AE%97%E5%87%BA%E7%9A%84%E9%83%A8%E5%88%86%22%5D%0A%20%20MATER%20--%3E%20REOPT%5B%22%E6%8C%89%E6%96%B0%E5%9F%BA%E6%95%B0%E9%87%8D%E8%B7%91%20DP%EF%BC%9A%E6%8D%A2%E5%BD%92%E5%B9%B6%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20REOPT%20--%3E%20RESUME%5B%22%E5%90%8C%E4%B8%80%E5%BF%AB%E7%85%A7%E4%B8%8B%E7%BB%A7%E7%BB%AD%E5%89%A9%E4%BD%99%E6%A0%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">常见误区：初学者容易以为自适应能拯救一切查询。重优化本身有成本——暂停、物化、再跑一次 DP；对几毫秒的 OLTP 短查询，这些开销可能比查询本身还贵。它真正的主场是动辄几分钟的 OLAP 长查询。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把强化学习优化器当 AQP 的同义词。提示与冻结计划是反自适应：DBA 不要执行中途变。计划回归课会谈「自动换计划」的运维恐惧。</p><p>后课默认：长查询可以设监测点；短查询信静态计划加统计。学习型优化器把历史反馈变成下一次的搜索先验。</p><p>自适应补的是估计失败，不是执行引擎的向量化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>监测实际基数，超阈则物化并重优化剩余树。</li><li>指称与快照必须不变；短查询往往不值得。</li><li>学习型优化器下一课：把多次反馈收成模型。</li><li>出处：Kabra and DeWitt；Avnur and Hellerstein；Deshpande, Ives and Raman。</li></ul>',7))])}const f=l(p,[["render",D]]);export{c as __pageData,f as default};
